endpoint.request:
employment?: {
  ...campi esistenti invariati,
  business_function_ids?: int[] | null   // assente o null = invariato; [] = svuota (poi D-4 decide); distinct, exists:business_functions,id
  product_lines?: [...]                  // invariato, ora facoltativo anche per utente attivo
}

endpoint.response:
data: User {
  ...invariato,
  managed_business_functions: [{ id: int, name: string }],      // ordinate per name
  employment?: {
    ...invariato,
    business_function_ids: int[],
    business_functions: [{ id: int, name: string }]             // ordinate per name
  }
}

data: {
  functions: [...invariato, persone = membri via pivot],
  unassigned_people: Person[]    // SOSTITUISCE all_functions_people; stessa shape Person
}
